const RANGES = ['Last 30 Days', 'Last 90 Days', 'Last 120 Days', '2026', '2025'];

const form = (range) => `<form action="/myaccount/orderhistory" id="OrderHistoryFilterForm" method="post">`
  + '<input name="__RequestVerificationToken" type="hidden" value="TEST-TOKEN">'
  + '<input id="ClearSessionFilters" name="ClearSessionFilters" type="hidden" value="false">'
  + '<input id="SearchString" name="SearchString" type="text">'
  + `<select id="DateRange" name="DateRange">${RANGES.map((r) => `<option${r === range ? ' selected="selected"' : ''}>${r}</option>`).join('')}</select></form>`;

const pager = (current, total) => '<div class="pageView"><div class="pager">'
  + Array.from({ length: total }, (_, i) => i + 1).map((n) => (n === current
    ? `<span class="pages currentPage">${n}</span>`
    : `<a href="https://store.tcgplayer.com/myaccount/orderhistory?PageNumber=${n}" class=" pages">${n}</a>`)).join('')
  + '</div></div>';

/** One page of results: which orders, which page of how many, and which range is selected. */
export function orderPage({ orders, page = 1, pages = 1, total = orders.length, range = 'Last 30 Days' }) {
  const first = (page - 1) * 10 + 1;
  return '<!doctype html><html><head><title>Order History</title></head><body>'
    + `<div class="orderFilter">${form(range)}</div>`
    + `<div class="breadcrumbs"><span>Viewing ${first} - ${first + orders.length - 1} of ${total} order(s)</span></div>`
    + `<div id="SellerOrderWidgetWrap">${orders.join('')}</div>${pages > 1 ? pager(page, pages) : ''}</body></html>`;
}

